def task_func(url, table_id):
    response = requests.get(url, verify=False)
    response.raise_for_status()

    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', {'id': table_id})

    if table is None:
        raise ValueError("Table with the specified ID not found.")

    rows = table.find_all('tr')
    if not rows:
        return pd.DataFrame()

    header = [th.text.strip() for th in rows[0].find_all(['th', 'td'])]
    data = []
    for row in rows[1:]:
        cells = row.find_all('td')
        if cells:
            data.append([cell.text.strip() for cell in cells])

    if not data:
        return pd.DataFrame(columns=header) if header else pd.DataFrame()

    return pd.DataFrame(data, columns=header if len(header) == len(data[0]) else None)

